mapper.select:
SELECT COUNT(*)
FROM investigation
WHERE incident_id = #{incidentId}

mapper.update:
UPDATE investigation
SET stop_requested_at = #{stopRequestedAt},
    stop_requested_by = #{stopRequestedBy},
    updated_at = #{stopRequestedAt},
    lock_version = lock_version + 1
WHERE id = #{id}
  AND current_run_no = #{expectedRunNo}
  AND lock_version = #{expectedVersion}
  AND stop_requested_at IS NULL

UPDATE investigation
SET current_run_capability_count = #{currentRunCount},
    capability_call_count = #{totalCount},
    updated_at = #{updatedAt},
    lock_version = lock_version + 1
WHERE id = #{id}
  AND current_run_no = #{expectedRunNo}
  AND lock_version = #{expectedVersion}

UPDATE investigation
SET consecutive_ai_failure_count = #{count},
    updated_at = #{updatedAt},
    lock_version = lock_version + 1
WHERE id = #{id}
  AND current_run_no = #{expectedRunNo}
  AND lock_version = #{expectedVersion}
